-- =====================================================================
-- Shaggar City KPI & Performance Management System — database schema
-- Portable SQL: runs on SQLite 3.35+ (default) and PostgreSQL 13+ (Neon).
-- For PostgreSQL, backend/db.js reads REAL as DOUBLE PRECISION.
-- Conventions
--   * Primary keys are TEXT identifiers generated by the application.
--   * Timestamps are ISO-8601 UTC strings (TEXT).
--   * Booleans are INTEGER 0/1.
--   * Flexible structures (settings, audit before/after) are JSON in TEXT.
-- =====================================================================

-- ---------- organisation & configuration ----------
CREATE TABLE IF NOT EXISTS settings (
  key         TEXT PRIMARY KEY,            -- e.g. 'branding', 'scoring', 'security', 'workflow'
  value       TEXT NOT NULL,               -- JSON
  updated_at  TEXT NOT NULL,
  updated_by  TEXT
);

CREATE TABLE IF NOT EXISTS departments (
  id          TEXT PRIMARY KEY,            -- short code, e.g. 'REV'
  name        TEXT NOT NULL,
  short_name  TEXT NOT NULL,
  head_user_id TEXT,
  active      INTEGER NOT NULL DEFAULT 1,
  created_at  TEXT NOT NULL
);

-- ---------- identity & access ----------
CREATE TABLE IF NOT EXISTS users (
  id              TEXT PRIMARY KEY,
  username        TEXT NOT NULL UNIQUE,
  name            TEXT NOT NULL,
  role            TEXT NOT NULL,           -- super_admin | mayor | mayor_admin | dept_head | staff | kpi_officer | auditor
  dept_id         TEXT REFERENCES departments(id),
  title           TEXT,
  phone           TEXT,
  email           TEXT,
  pref_sms        INTEGER NOT NULL DEFAULT 1,
  pref_email      INTEGER NOT NULL DEFAULT 1,
  lang            TEXT NOT NULL DEFAULT 'en',
  password_hash   TEXT NOT NULL,           -- PBKDF2-SHA256, base64
  password_salt   TEXT NOT NULL,
  failed_attempts INTEGER NOT NULL DEFAULT 0,
  locked_until    TEXT,
  must_change     INTEGER NOT NULL DEFAULT 0,
  active          INTEGER NOT NULL DEFAULT 1,
  last_login      TEXT,
  created_at      TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_users_dept ON users(dept_id);

CREATE TABLE IF NOT EXISTS role_permissions (
  role        TEXT NOT NULL,
  permission  TEXT NOT NULL,
  PRIMARY KEY (role, permission)
);

CREATE TABLE IF NOT EXISTS sessions (
  token_hash  TEXT PRIMARY KEY,            -- SHA-256 of the session token (token itself is only in the cookie)
  user_id     TEXT NOT NULL REFERENCES users(id),
  created_at  TEXT NOT NULL,
  last_seen   TEXT NOT NULL,
  expires_at  TEXT NOT NULL,
  ip          TEXT,
  user_agent  TEXT
);

CREATE TABLE IF NOT EXISTS otp_challenges (
  id          TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL REFERENCES users(id),
  code_hash   TEXT NOT NULL,
  expires_at  TEXT NOT NULL,
  attempts    INTEGER NOT NULL DEFAULT 0,
  created_at  TEXT NOT NULL
);

-- ---------- strategy & KPIs ----------
CREATE TABLE IF NOT EXISTS objectives (
  id          TEXT PRIMARY KEY,            -- e.g. 'SO1'
  title       TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS kpis (
  id                TEXT PRIMARY KEY,
  code              TEXT NOT NULL UNIQUE,  -- e.g. 'REV-01'
  dept_id           TEXT NOT NULL REFERENCES departments(id),
  objective_id      TEXT REFERENCES objectives(id),
  name              TEXT NOT NULL,
  definition        TEXT,
  formula           TEXT,
  source            TEXT,                  -- data source / means of verification
  unit              TEXT NOT NULL,
  direction         TEXT NOT NULL,         -- higher | lower
  frequency         TEXT NOT NULL,         -- monthly | quarterly
  aggregation       TEXT NOT NULL,         -- sum | avg
  weight            REAL NOT NULL,
  annual_target     REAL NOT NULL,
  baseline          REAL,
  evidence_required INTEGER NOT NULL DEFAULT 1,
  owner_id          TEXT REFERENCES users(id),
  active            INTEGER NOT NULL DEFAULT 1,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  targets_approved_at TEXT,                -- set when the Mayor's Office approves the targets (targets are then locked)
  targets_approved_by TEXT,
  approval          TEXT NOT NULL DEFAULT 'approved',  -- proposed | returned | approved. A KPI proposed by a department stays inactive until approved.
  proposed_by       TEXT,
  decided_by        TEXT,
  decision_comment  TEXT
);
CREATE INDEX IF NOT EXISTS idx_kpis_dept ON kpis(dept_id);

CREATE TABLE IF NOT EXISTS kpi_targets (
  kpi_id      TEXT NOT NULL REFERENCES kpis(id),
  month       INTEGER NOT NULL,            -- 0 = July … 11 = June (fiscal year)
  target      REAL,
  PRIMARY KEY (kpi_id, month)
);

-- Targets are proposed by the department and approved by the Mayor's Office.
-- An approved proposal is copied into kpis.annual_target and kpi_targets.
CREATE TABLE IF NOT EXISTS target_proposals (
  id            TEXT PRIMARY KEY,
  kpi_id        TEXT NOT NULL REFERENCES kpis(id),
  annual        REAL NOT NULL,
  targets       TEXT NOT NULL,             -- JSON array of 12 monthly targets (null = not a reporting month)
  reason        TEXT,                      -- required when revising targets that are already approved
  is_revision   INTEGER NOT NULL DEFAULT 0,
  status        TEXT NOT NULL,             -- pending | approved | returned | withdrawn
  proposed_by   TEXT REFERENCES users(id),
  proposed_at   TEXT NOT NULL,
  decided_by    TEXT REFERENCES users(id),
  decided_at    TEXT,
  decision_comment TEXT
);
CREATE INDEX IF NOT EXISTS idx_tp_status ON target_proposals(status);

CREATE TABLE IF NOT EXISTS kpi_prev_year (
  kpi_id      TEXT NOT NULL REFERENCES kpis(id),
  quarter     INTEGER NOT NULL,            -- 0..3
  target      REAL NOT NULL,
  actual      REAL NOT NULL,
  PRIMARY KEY (kpi_id, quarter)
);

-- ---------- performance reporting ----------
CREATE TABLE IF NOT EXISTS submissions (
  id            TEXT PRIMARY KEY,
  kpi_id        TEXT NOT NULL REFERENCES kpis(id),
  month         INTEGER NOT NULL,
  actual        REAL,
  note          TEXT,
  status        TEXT NOT NULL,             -- draft | submitted | verified | approved | returned
  submitted_by  TEXT REFERENCES users(id),
  submitted_at  TEXT,
  verified_by   TEXT REFERENCES users(id),
  verified_at   TEXT,
  approved_by   TEXT REFERENCES users(id),
  approved_at   TEXT,
  esc_verify    INTEGER NOT NULL DEFAULT 0,
  esc_approve   INTEGER NOT NULL DEFAULT 0,
  UNIQUE (kpi_id, month)
);
CREATE INDEX IF NOT EXISTS idx_sub_status ON submissions(status);

CREATE TABLE IF NOT EXISTS submission_evidence (
  id            TEXT PRIMARY KEY,
  submission_id TEXT NOT NULL REFERENCES submissions(id),
  file_name     TEXT NOT NULL,
  size          INTEGER NOT NULL,
  mime          TEXT,
  storage_path  TEXT,                      -- relative path under storage/uploads (NULL for seeded metadata)
  sha256        TEXT,
  uploaded_by   TEXT REFERENCES users(id),
  uploaded_at   TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS submission_history (
  id            TEXT PRIMARY KEY,
  submission_id TEXT NOT NULL REFERENCES submissions(id),
  user_id       TEXT REFERENCES users(id), -- NULL = system
  action        TEXT NOT NULL,
  comment       TEXT,
  at            TEXT NOT NULL
);

-- ---------- corrective action plans ----------
CREATE TABLE IF NOT EXISTS action_plans (
  id            TEXT PRIMARY KEY,
  ref           TEXT NOT NULL UNIQUE,      -- CAP-2026-001
  dept_id       TEXT NOT NULL REFERENCES departments(id),
  kpi_id        TEXT REFERENCES kpis(id),
  title         TEXT NOT NULL,
  trigger_text  TEXT,
  root_cause    TEXT,
  status        TEXT NOT NULL,             -- Open | In progress | Completed
  created_by    TEXT REFERENCES users(id),
  created_at    TEXT NOT NULL,
  completed_at  TEXT,
  archived_at   TEXT
);

CREATE TABLE IF NOT EXISTS action_items (
  id            TEXT PRIMARY KEY,
  plan_id       TEXT NOT NULL REFERENCES action_plans(id),
  position      INTEGER NOT NULL,
  text          TEXT NOT NULL,
  owner_id      TEXT REFERENCES users(id),
  due_date      TEXT NOT NULL,
  done          INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS action_updates (
  id            TEXT PRIMARY KEY,
  plan_id       TEXT NOT NULL REFERENCES action_plans(id),
  kind          TEXT NOT NULL,             -- update | review
  user_id       TEXT REFERENCES users(id),
  text          TEXT NOT NULL,
  at            TEXT NOT NULL
);

-- ---------- employees ----------
CREATE TABLE IF NOT EXISTS employees (
  id            TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  position      TEXT,
  dept_id       TEXT NOT NULL REFERENCES departments(id),
  user_id       TEXT REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS employee_indicators (
  id            TEXT PRIMARY KEY,
  employee_id   TEXT NOT NULL REFERENCES employees(id),
  position      INTEGER NOT NULL,
  name          TEXT NOT NULL,
  unit          TEXT,
  direction     TEXT NOT NULL,
  target        REAL NOT NULL,
  actual        REAL,                      -- verified actual (counts towards the score)
  weight        REAL NOT NULL,
  kpi_id        TEXT,                      -- department KPI this indicator contributes to (optional)
  status        TEXT NOT NULL DEFAULT 'approved',   -- proposed | approved | returned  (indicator and its target)
  proposed_by   TEXT,
  decision_comment TEXT,
  reported_actual REAL,                    -- figure reported by the employee, waiting for verification
  report_note   TEXT,
  report_status TEXT NOT NULL DEFAULT 'none',       -- none | reported | verified | returned
  reported_at   TEXT,
  verified_by   TEXT,
  verified_at   TEXT,
  verify_comment TEXT
);

CREATE TABLE IF NOT EXISTS employee_evidence (
  id            TEXT PRIMARY KEY,
  indicator_id  TEXT NOT NULL REFERENCES employee_indicators(id),
  file_name     TEXT NOT NULL,
  size          INTEGER NOT NULL,
  mime          TEXT,
  storage_path  TEXT,
  sha256        TEXT,
  uploaded_by   TEXT REFERENCES users(id),
  uploaded_at   TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS employee_evaluations (
  id            TEXT PRIMARY KEY,
  employee_id   TEXT NOT NULL REFERENCES employees(id),
  period        TEXT NOT NULL,             -- e.g. 'Q1 FY2026/27'
  rating        TEXT NOT NULL,
  comment       TEXT,
  evaluated_by  TEXT REFERENCES users(id),
  at            TEXT NOT NULL
);

-- ---------- notifications ----------
CREATE TABLE IF NOT EXISTS notifications (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL REFERENCES users(id),
  text          TEXT NOT NULL,
  event         TEXT NOT NULL,
  link          TEXT,              -- what it is about, "kind:id"; opened on click
  is_read       INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_notif_user ON notifications(user_id, is_read);

CREATE TABLE IF NOT EXISTS outbox (
  id            TEXT PRIMARY KEY,
  channel       TEXT NOT NULL,             -- sms | email
  recipient     TEXT NOT NULL,
  user_id       TEXT REFERENCES users(id),
  text          TEXT NOT NULL,
  event         TEXT NOT NULL,
  status        TEXT NOT NULL,             -- held | sent | failed
  created_at    TEXT NOT NULL,
  sent_at       TEXT
);

-- ---------- internal messaging (one-to-one between staff accounts) ----------
CREATE TABLE IF NOT EXISTS messages (
  id            TEXT PRIMARY KEY,
  from_id       TEXT NOT NULL REFERENCES users(id),
  to_id         TEXT NOT NULL REFERENCES users(id),
  body          TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  read_at       TEXT
);
CREATE INDEX IF NOT EXISTS idx_msg_to ON messages(to_id, read_at);
CREATE INDEX IF NOT EXISTS idx_msg_pair ON messages(from_id, to_id);

-- ---------- audit ----------
CREATE TABLE IF NOT EXISTS audit_log (
  id            TEXT PRIMARY KEY,
  at            TEXT NOT NULL,
  user_id       TEXT,                      -- NULL = system
  role          TEXT,
  action        TEXT NOT NULL,
  category      TEXT NOT NULL,
  entity        TEXT NOT NULL,
  entity_id     TEXT,
  details       TEXT,
  before_json   TEXT,
  after_json    TEXT,
  ip            TEXT
);
CREATE INDEX IF NOT EXISTS idx_audit_at ON audit_log(at);
CREATE INDEX IF NOT EXISTS idx_audit_user ON audit_log(user_id);

-- ---------- integrations ----------
CREATE TABLE IF NOT EXISTS api_keys (
  id            TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  prefix        TEXT NOT NULL,
  key_hash      TEXT NOT NULL UNIQUE,      -- SHA-256 of the full key
  scopes        TEXT NOT NULL,             -- comma-separated
  created_by    TEXT REFERENCES users(id),
  created_at    TEXT NOT NULL,
  last_used     TEXT,
  revoked       INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS webhooks (
  id            TEXT PRIMARY KEY,
  url           TEXT NOT NULL,
  events        TEXT NOT NULL,             -- comma-separated
  secret        TEXT NOT NULL,
  active        INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL
);

-- ---------- operations ----------
CREATE TABLE IF NOT EXISTS backups (
  id            TEXT PRIMARY KEY,
  created_at    TEXT NOT NULL,
  created_by    TEXT,
  kind          TEXT NOT NULL,             -- manual | daily | pre-restore
  size          INTEGER NOT NULL,
  checksum      TEXT NOT NULL,             -- SHA-256 of the backup file
  file_name     TEXT NOT NULL,
  format        TEXT NOT NULL DEFAULT 'json' -- json (both engines, since v1.5) | sqlite (older file copies)
);

CREATE TABLE IF NOT EXISTS qa_sessions (
  id            TEXT PRIMARY KEY,
  role          TEXT NOT NULL,
  task          TEXT NOT NULL,
  status        TEXT NOT NULL,
  findings      TEXT
);

CREATE TABLE IF NOT EXISTS qa_runs (
  id            TEXT PRIMARY KEY,
  at            TEXT NOT NULL,
  run_by        TEXT REFERENCES users(id),
  passed        INTEGER NOT NULL,
  results       TEXT NOT NULL              -- JSON
);

CREATE TABLE IF NOT EXISTS schema_version (
  version       INTEGER PRIMARY KEY,
  applied_at    TEXT NOT NULL
);
